CREATE TABLE change_history (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 batch_id TEXT NOT NULL, table_name TEXT NOT NULL, row_key TEXT NOT NULL,
 class_id TEXT, course_id TEXT, label TEXT NOT NULL,
 before_data TEXT, after_data TEXT,
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), undone_at TEXT
);
CREATE INDEX history_batch ON change_history(batch_id,id);
CREATE INDEX history_class ON change_history(class_id,id);
CREATE TABLE history_context (id INTEGER PRIMARY KEY CHECK(id=1), batch_id TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0);
INSERT INTO history_context(id,batch_id) VALUES(1,lower(hex(randomblob(16))));
CREATE TRIGGER history_courses_update AFTER UPDATE ON courses WHEN (SELECT disabled FROM history_context WHERE id=1)=0 AND (OLD.id IS NOT NEW.id OR OLD.level IS NOT NEW.level OR OLD.subject IS NOT NEW.subject OR OLD.type IS NOT NEW.type OR OLD.peso_criterios_manual IS NOT NEW.peso_criterios_manual) BEGIN
 INSERT INTO change_history(batch_id,table_name,row_key,class_id,course_id,label,before_data,after_data) VALUES((SELECT batch_id FROM history_context WHERE id=1),'courses',NEW.id,NULL,NEW.id,NEW.subject,json_object('id',OLD.id,'level',OLD.level,'subject',OLD.subject,'type',OLD.type,'peso_criterios_manual',json(CASE WHEN OLD.peso_criterios_manual IS NULL THEN 'null' WHEN OLD.peso_criterios_manual=0 THEN 'false' ELSE 'true' END),'created_at',OLD.created_at,'updated_at',OLD.updated_at),json_object('id',NEW.id,'level',NEW.level,'subject',NEW.subject,'type',NEW.type,'peso_criterios_manual',json(CASE WHEN NEW.peso_criterios_manual IS NULL THEN 'null' WHEN NEW.peso_criterios_manual=0 THEN 'false' ELSE 'true' END),'created_at',NEW.created_at,'updated_at',NEW.updated_at));
END;
CREATE TRIGGER history_courses_delete AFTER DELETE ON courses WHEN (SELECT disabled FROM history_context WHERE id=1)=0 BEGIN
 INSERT INTO change_history(batch_id,table_name,row_key,class_id,course_id,label,before_data,after_data) VALUES((SELECT batch_id FROM history_context WHERE id=1),'courses',OLD.id,NULL,OLD.id,OLD.subject,json_object('id',OLD.id,'level',OLD.level,'subject',OLD.subject,'type',OLD.type,'peso_criterios_manual',json(CASE WHEN OLD.peso_criterios_manual IS NULL THEN 'null' WHEN OLD.peso_criterios_manual=0 THEN 'false' ELSE 'true' END),'created_at',OLD.created_at,'updated_at',OLD.updated_at),NULL);
END;
