CREATE TRIGGER history_assignments_update AFTER UPDATE ON assignments WHEN (SELECT disabled FROM history_context WHERE id=1)=0 AND (OLD.id IS NOT NEW.id OR OLD.class_id IS NOT NEW.class_id OR OLD.category_id IS NOT NEW.category_id OR OLD.evaluation_period_id IS NOT NEW.evaluation_period_id OR OLD.evaluation_tool_id IS NOT NEW.evaluation_tool_id OR OLD.programming_unit_id IS NOT NEW.programming_unit_id OR OLD.name IS NOT NEW.name OR OLD.date IS NOT NEW.date OR OLD.evaluation_method IS NOT NEW.evaluation_method OR OLD.linked_criteria IS NOT NEW.linked_criteria OR OLD.recovers_assignment_ids IS NOT NEW.recovers_assignment_ids OR OLD.peso_en_categoria IS NOT NEW.peso_en_categoria OR OLD.importancia IS NOT NEW.importancia OR OLD.importancia_personalizada IS NOT NEW.importancia_personalizada OR OLD.short_name IS NOT NEW.short_name OR OLD.puntuacion_maxima IS NOT NEW.puntuacion_maxima OR OLD.assignment_group IS NOT NEW.assignment_group OR OLD.column_order IS NOT NEW.column_order) BEGIN
