CREATE TRIGGER history_grades_insert AFTER INSERT ON grades WHEN (SELECT disabled FROM history_context WHERE id=1)=0 BEGIN
 INSERT INTO change_history(batch_id,table_name,row_key,class_id,course_id,label,before_data,after_data) VALUES((SELECT batch_id FROM history_context WHERE id=1),'grades',NEW.enrollment_id || '|' || NEW.assignment_id,(SELECT class_id FROM assignments WHERE id=NEW.assignment_id),NULL,COALESCE((SELECT name FROM assignments WHERE id=NEW.assignment_id),'Nota de tarea eliminada'),NULL,json_object('enrollment_id',NEW.enrollment_id,'assignment_id',NEW.assignment_id,'direct_score',NEW.direct_score,'recovery_score',NEW.recovery_score,'tool_results',json(NEW.tool_results),'updated_at',NEW.updated_at,'direct_score_raw',NEW.direct_score_raw));
END;
CREATE TRIGGER history_grades_update AFTER UPDATE ON grades WHEN (SELECT disabled FROM history_context WHERE id=1)=0 AND (OLD.enrollment_id IS NOT NEW.enrollment_id OR OLD.assignment_id IS NOT NEW.assignment_id OR OLD.direct_score IS NOT NEW.direct_score OR OLD.recovery_score IS NOT NEW.recovery_score OR OLD.tool_results IS NOT NEW.tool_results OR OLD.direct_score_raw IS NOT NEW.direct_score_raw) BEGIN
